-- Create table for legal documents
CREATE TABLE IF NOT EXISTS public.legal_documents (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS for legal_documents
ALTER TABLE public.legal_documents ENABLE ROW LEVEL SECURITY;

-- Allow public read access to legal documents
CREATE POLICY "Public read access to legal documents" ON public.legal_documents FOR SELECT USING (true);

-- Allow authenticated admins to insert/update/delete (assuming simple authenticated role for now, adjust based on admin role logic)
CREATE POLICY "Admins can manage legal documents" ON public.legal_documents FOR ALL USING (auth.role() = 'authenticated');

-- Create table for cookie consent logs
CREATE TABLE IF NOT EXISTS public.cookie_consent_logs (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  action TEXT NOT NULL CHECK (action IN ('accepted', 'rejected')),
  ip_address TEXT,
  user_agent TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS for cookie_consent_logs
ALTER TABLE public.cookie_consent_logs ENABLE ROW LEVEL SECURITY;

-- Allow anyone to insert consent logs (anon and authenticated)
CREATE POLICY "Anyone can insert consent logs" ON public.cookie_consent_logs FOR INSERT WITH CHECK (true);

-- Allow authenticated users to view consent logs
CREATE POLICY "Authenticated users can view consent logs" ON public.cookie_consent_logs FOR SELECT USING (auth.role() = 'authenticated');


-- Seed Data

-- Delete existing to avoid duplicates if rerun
DELETE FROM public.legal_documents WHERE slug IN ('privacy-policy', 'terms-and-conditions');

INSERT INTO public.legal_documents (slug, title, content) VALUES
(
  'privacy-policy',
  'Privacy Policy',
  '<p><strong>Effective Date:</strong> 09/01/2026<br><strong>Last Updated:</strong> 08/01/2026<br><strong>Website:</strong> www.diverseloopers.com<br><strong>Contact:</strong> contact@diverseloopers.com | +91 98393 50961</p><p>This document governs your use of the Diverse Loopers platform and applies equally to all categories of users including Students, Business Partners, University & Institutional Partners, Visitors, and Mentors. By accessing or using this website, you acknowledge that you have read, understood, and agreed to be bound by all terms stated herein.</p><h2>PART A — PRIVACY POLICY</h2><h3>1. Our Commitment to Privacy</h3><p>Diverse Loopers ("we", "us", "our", or "the Platform") is committed to protecting the privacy and personal data of every individual who interacts with our platform. This commitment is grounded in the fundamental right to privacy recognized by the Supreme Court of India in K.S. Puttaswamy v. Union of India (2017) 10 SCC 1, which held that the right to privacy is an intrinsic part of the right to life and personal liberty guaranteed under Article 21 of the Constitution of India.</p><p>We further operate in compliance with:</p><ul><li>The Information Technology Act, 2000 and its amendments</li><li>The Information Technology (Reasonable Security Practices and Procedures and Sensitive Personal Data or Information) Rules, 2011 ("SPDI Rules")</li><li>The Digital Personal Data Protection Act, 2023 ("DPDP Act")</li><li>The Consumer Protection Act, 2019</li><li>All applicable rules and regulations issued by the Ministry of Electronics and Information Technology (MeitY)</li></ul><p>As recognized under Article 19(1)(a) of the Constitution of India, the right to freedom of expression includes the right to receive and impart information. We ensure that our data practices respect this right while simultaneously safeguarding Article 21 protections for informational privacy.</p><h3>2. Who This Policy Applies To</h3><p>This Privacy Policy applies to:</p><ul><li><strong>2.1 Students and Learners</strong> — Individuals who register for programs, enroll in the Hybrid Hustle model, use the Career Analyzer, Path Analyzer, SkillSynth tools, attend webinars or workshops, or interact with our mentors.</li><li><strong>2.2 Business Partners</strong> — Companies, startups, entrepreneurs, or organizations that submit project delivery requests, talent hiring inquiries, or partnership proposals through our Business portal.</li><li><strong>2.3 University and Institutional Partners</strong> — Educational institutions, colleges, universities, placement cells, or faculty members who engage with Diverse Loopers for academic collaboration, departmental pilots, or innovation lab partnerships.</li><li><strong>2.4 Mentors and Professionals</strong> — Industry professionals who register on the platform to offer mentorship, career guidance, or technical reviews.</li><li><strong>2.5 General Visitors</strong> — Any individual who browses the website at www.diverseloopers.com without formally registering.</li></ul><h3>3. What Personal Data We Collect</h3><p>We collect the following categories of personal data, depending on how you interact with our platform:</p><ul><li><strong>3.1 Identity and Contact Information</strong>: Full name, email address, phone number, college or institution name, roll number, course year, semester details, designation, and official business email.</li><li><strong>3.2 Academic and Professional Information</strong>: Domain of study or work, technology interest areas, academic performance inputs, career preference assessment responses, course enrollment data, and project contribution records.</li><li><strong>3.3 Business and Organizational Information</strong>: Company name, business contact person, type of inquiry, preferred hiring roles, technology stack requirements, and custom project scope details.</li><li><strong>3.4 Usage and Technical Data</strong>: IP address, browser type and version, device type and operating system, pages visited, time spent on each page, referring URL, session duration, and interaction data such as clicks and form submissions.</li><li><strong>3.5 Communication Data</strong>: Messages sent through the contact form, WhatsApp community participation, emails exchanged with our team, and feedback provided during programs or mentorship sessions.</li><li><strong>3.6 Portfolio and Performance Data</strong>: Project work submitted through the platform, peer review records, mentor-approved portfolio entries, and Wall of Fame recognition data (which is public by nature of its purpose).</li></ul><h3>4. How We Collect Your Data</h3><p>We collect data through the following means:</p><ul><li>Directly from you when you fill in registration forms, enrollment forms, contact forms, or partner inquiry forms on our website</li><li>Automatically through cookies, analytics scripts, and server logs when you visit our website</li><li>Through third-party integrations such as Google Analytics, WhatsApp, LinkedIn, and Instagram when you interact with our social media pages or embedded tools</li><li>Through communications you initiate with us via email, phone, or WhatsApp</li></ul><h3>5. Why We Collect Your Data — Purpose of Processing</h3><p>In accordance with Section 5 of the DPDP Act, 2023, personal data shall be processed only for a lawful purpose for which the Data Principal has given consent or which is permitted by law. We collect and process your data for the following specific, lawful purposes:</p><ul><li><strong>For Students</strong>: To enroll you in programs, provide career analysis, connect you with mentors, display achievements (with consent), and issue certificates.</li><li><strong>For Business Partners</strong>: To process inquiries, match requirements with contributors, communicate timelines, and maintain NDA records.</li><li><strong>For University Partners</strong>: To manage co-creation discussions, share pilot outcomes, and coordinate faculty training.</li><li><strong>For All Users</strong>: To operate our website, comply with Indian law, protect against fraud, and respond to queries.</li></ul><h3>6. Legal Basis for Processing</h3><p>We process your personal data on the following legal bases:</p><ul><li><strong>Consent</strong> — Where you have voluntarily provided your data. As required under Section 6 of the DPDP Act, 2023, consent is free, specific, informed, and unambiguous.</li><li><strong>Contractual Necessity</strong> — Where processing is necessary to fulfill our obligations to you.</li><li><strong>Legitimate Interests</strong> — For internal analytics, platform improvement, and security monitoring.</li><li><strong>Legal Compliance</strong> — Where required by applicable Indian law.</li></ul><h3>7. Sensitive Personal Data</h3><p>As per the IT (SPDI) Rules, 2011, Diverse Loopers does not knowingly collect categories such as passwords in plain text, financial information, or biometric data. Where any sensitive data is involved, we apply additional safeguards and do not share it without explicit consent.</p><h3>8. Data Sharing and Disclosure</h3><p>We do not sell, rent, or trade your personal data. We may share your data in limited circumstances with mentors, business partners (opt-in only), service providers (hosting, analytics), university partners (aggregated data), and for legal compliance as permitted under Section 8 of the DPDP Act, 2023.</p><h3>9. Data Retention</h3><p>We retain your personal data for as long as necessary. Student data is retained for 3 years from last activity, business inquiries for 2 years, contact forms for 1 year, and analytics in anonymized form for up to 3 years. Legal records are retained as required by Indian law, including the Limitation Act, 1963.</p><h3>10. Your Rights as a Data Principal</h3><p>Under the DPDP Act, 2023, you have the Right to Access, Correction and Erasure, Grievance Redressal, Withdraw Consent, and Nominate another individual to exercise rights on your behalf. To exercise these, email contact@diverseloopers.com.</p><h3>11. Data Security</h3><p>We implement reasonable security practices as per Rule 8 of the IT (SPDI) Rules, 2011, including secure HTTPS transmission, access controls, and regular reviews.</p><h3>12. Children''s Privacy</h3><p>We do not knowingly collect personal data from children below 18 without verifiable parental consent (Section 9, DPDP Act 2023).</p><h3>13. Third-Party Links</h3><p>Our Privacy Policy does not apply to third-party platforms linked on our site (LinkedIn, Instagram, WhatsApp).</p><h3>14. Grievance Officer</h3><p>Email: contact@diverseloopers.com | Phone: +91 98393 50961 | Response Time: Within 30 days.</p><h2>PART C — COOKIE POLICY</h2><p>Cookies are small text files placed on your device to make websites function correctly and improve performance. We use Strictly Necessary Cookies, Performance and Analytics Cookies (Google Analytics), Functional Cookies, and Social Media Cookies.</p><p>In alignment with Section 6 of the DPDP Act, 2023, we display a cookie consent notice when you first visit our website. You may accept or decline non-essential cookies. You can also manage cookies through your browser settings.</p><h2>PART D — GENERAL PROVISIONS</h2><p>Our operations are underpinned by the Constitution of India (Articles 14, 19(1)(a), 19(1)(g), 21, 21A, 39A) and applicable Indian laws including the IT Act 2000, DPDP Act 2023, Consumer Protection Act 2019, Copyright Act 1957, and Trade Marks Act 1999.</p>'
),
(
  'terms-and-conditions',
  'Terms and Conditions',
  '<p><strong>Effective Date:</strong> 08/01/2026<br><strong>Last Updated:</strong> 09/01/2026<br><strong>Website:</strong> www.diverseloopers.com<br><strong>Email:</strong> contact@diverseloopers.com<br><strong>Phone:</strong> +91 98393 50961</p><p>PLEASE READ THESE TERMS AND CONDITIONS CAREFULLY BEFORE USING THIS PLATFORM. BY ACCESSING OR USING WWW.DIVERSELOOPERS.COM OR ANY SERVICE OFFERED BY DIVERSE LOOPERS, YOU CONFIRM THAT YOU HAVE READ, UNDERSTOOD, AND AGREE TO BE LEGALLY BOUND BY THESE TERMS.</p><h3>1. INTRODUCTION AND PARTIES</h3><p>These Terms constitute a legally binding agreement between Diverse Loopers and any individual or entity who accesses the platform. This agreement is recognized under Section 10 of the Indian Contract Act, 1872.</p><h3>2. ELIGIBILITY AND CAPACITY TO CONTRACT</h3><p>You must be at least 18 years of age, or have verified consent from a parent/guardian. Minors are not competent to contract under Section 11 of the Indian Contract Act, 1872.</p><h3>3. ACCOUNT REGISTRATION AND SECURITY</h3><p>You agree to provide accurate information and maintain the confidentiality of your login credentials.</p><h3>4. DESCRIPTION OF SERVICES</h3><p>We provide Structured Learning Programs, the Hybrid Hustle Program, Career Compass Tools, Mentorship, and Business/Institutional Partnerships.</p><h3>5. HYBRID HUSTLE PROGRAM</h3><p>Enrollment does not create an employment relationship. Earning opportunities are performance-based; there is no guaranteed income. Intellectual property of project work vests with Diverse Loopers or the client.</p><h3>6. BUSINESS PARTNER TERMS</h3><p>Business partners agree not to directly recruit or independently hire student contributors without express written consent. A 12-month non-solicitation period applies.</p><h3>7. UNIVERSITY AND INSTITUTIONAL PARTNER TERMS</h3><p>Partnerships are formalized through MoUs. Diverse Loopers does not guarantee specific placement rates.</p><h3>8. MENTOR TERMS</h3><p>Mentors operate as independent professionals and agree to maintain confidentiality of student information.</p><h3>9. USER CONDUCT</h3><p>Users agree not to engage in unlawful activities, harassment, unauthorized access, or distribution of proprietary content.</p><h3>10. FEES AND PAYMENTS</h3><p>Fees are in INR and inclusive of GST. Payments are generally non-refundable unless specified otherwise.</p><h3>11. INTELLECTUAL PROPERTY RIGHTS</h3><p>All content and the Hybrid Hustle® model are exclusive property of Diverse Loopers, protected under the Copyright Act, 1957. You are granted a limited, non-commercial licence to use the platform.</p><h3>12. PRIVACY AND DATA PROTECTION</h3><p>Data processing is governed by our Privacy Policy and the DPDP Act, 2023.</p><h3>13. THIRD-PARTY LINKS</h3><p>We are not responsible for third-party platforms linked from our site.</p><h3>14. DISCLAIMERS</h3><p>The platform is provided "as is". Career tools generate AI suggestions for informational purposes only, not professional counseling.</p><h3>15. LIMITATION OF LIABILITY</h3><p>Liability is capped at the amount paid by the user in the preceding 12 months. We are not liable for indirect or consequential damages.</p><h3>16. INDEMNIFICATION</h3><p>You agree to indemnify Diverse Loopers against claims arising from your use of the platform or breach of these Terms.</p><h3>17. FORCE MAJEURE</h3><p>We are not liable for delays caused by circumstances beyond our reasonable control.</p><h3>18. GOVERNING LAW</h3><p>These Terms are governed by the laws of India, including the Indian Contract Act 1872, IT Act 2000, and DPDP Act 2023.</p><h3>19. DISPUTE RESOLUTION</h3><p>We encourage direct resolution first. Unresolved disputes shall be subject to binding arbitration in <strong>Delhi</strong> under the Arbitration and Conciliation Act, 1996. Both parties submit to the exclusive jurisdiction of the courts at <strong>Delhi</strong>, India.</p><h3>20. TERMINATION</h3><p>We may suspend or terminate access for breaches of these Terms.</p><h3>25. CONTACT INFORMATION</h3><p>Grievance Officer: contact@diverseloopers.com | +91 98393 50961</p>'
